810	  {
811	    "verse_id": "5.34.35",
812	    "sarga": 34,
813	    "verse": "35",
814	    "ambiguous_marker": false,
815	    "sanskrit_iast": "abhivādya mahābāhuḥ sa tvāṃ kauśalam abravīt । rāmasya ca sakhā devi sugrīvo nāma vānaraḥ ॥35॥",
816	    "leonov_ru": "Мощнорукий, приветствуя [тебя], спрашивает о твоем благополучии. У Рамы [есть] друг, царевна, обезьяна по имени Сугрива,",
817	    "commentary": {
818	      "siromani": "रामस्येति । रामस्य सखा सुग्रीवः कौशलमब्रवीत्"
819	    },
820	    "pratika_check": {
821	      "siromani": {
822	        "pratika_iast": "ranasyeti",
823	        "matches_verse": true
824	      }
825	    }
826	  },
827	  {
828	    "verse_id": "5.34.36",
829	    "sarga": 34,
830	    "verse": "36",
831	    "ambiguous_marker": false,
832	    "sanskrit_iast": "rājā vānaramukhyānāṃ sa tvāṃ kauśalam abravīt । nityaṃ smarati rāmas tvāṃ sasugrīvaḥ salakṣmaṇaḥ ॥36॥",
833	    "leonov_ru": "Царь вождей обезьян, он спрашивает о твоем благополучии. Всегда вспоминает о тебе Рама с Сугривой и Лакшманой.",
834	    "commentary": {
835	      "bhusana": "रामस्य च सखा देवि सुग्रीवो नाम वानरः ।\n\nराजा वानरमुख्यानां स त्वां कौशलमब्रवीत्\nनित्यं स्मरति रामस्त्वां ससुग्रीवः सलक्ष्मणः ।\n\nदिष्ट्या जीवसि वैदेहि राक्षसीवशमागता",
836	      "siromani": "नित्यमिति । ते त्वां रामो नित्यं स्मरति \"अधीगर्थ\" इति षष्ठी । हे वैदेहि राक्षसीवशमागतां त्वं दिष्ट्या भाग्यवशेन जीवसि\nननु त्वं को ऽसीत्यत आह अहमिति । सुग्रीवसचिवो हनूमानहं लङ्कां प्रविष्टो ऽस्मीति शेषः"
837	    },
838	    "pratika_check": {
839	      "bhusana": {
840	        "pratika_iast": "ranasya ca sakha devi",
841	        "matches_verse": true
842	      },
843	      "siromani": {
844	        "pratika_iast": "nityaniti",
845	        "matches_verse": true
846	      }
847	    }
848	  },
849	  {
850	    "verse_id": "5.34.37",
851	    "sarga": 34,
852	    "verse": "37",
853	    "ambiguous_marker": false,
854	    "sanskrit_iast": "diṣṭyā jīvasi vaidehi rākṣasī vaśam āgatā । nacirād drakṣyase rāmaṃ lakṣmaṇaṃ ca mahāratham ॥37॥",
855	    "leonov_ru": "Волей судьбы ты жива, Вайдехи, оказавшаяся во власти ракшаси. Скоро увидишь ты Раму и Лакшману, великого воина,",
856	    "commentary": {
857	      "siromani": "नेति । रामं लक्ष्मणं च वानरकोटीनाम् अनेककोटिसंख्याकवानराणां मध्ये सुग्रीवं च नचिरात् शीघ्रं द्रक्ष्यसे",
858	      "bhusana": "नचिराद्द्रक्ष्यसे रामं लक्ष्मणं च महाबलम् ।\n\nमध्ये वानरकोटीनां सुग्रीवं चामितौजसम्"
859	    },
860	    "pratika_check": {
861	      "siromani": {
862	        "pratika_iast": "neti",
863	        "matches_verse": false
864	      },
865	      "bhusana": {
866	        "pratika_iast": "naciraddraksyase ranan laksnanan ca",
867	        "matches_verse": true
868	      }
869	    }
