872	    "verse_id": "5.34.38",
873	    "sarga": 34,
874	    "verse": "38",
875	    "ambiguous_marker": false,
876	    "sanskrit_iast": "madhye vānarakoṭīnāṃ sugrīvaṃ cāmitaujasaṃ । ahaṃ sugrīvasacivo hanūmān nāma vānaraḥ ॥38॥",
877	    "leonov_ru": "И Сугриву, наделенного безмерной мощью, среди великого множества обезьян. Я советник Сугривы, обезьяна по имени Хануман.",
878	    "commentary": {
879	      "bhusana": "अहं सुग्रीवसचिवो हनुमान्नाम वानरः ।\n\nप्रविष्टो नगरीं लङ्कां लङ्घयित्वा महोदधिम्"
880	    },
881	    "pratika_check": {
