889	    "verse_id": "5.34.39",
890	    "sarga": 34,
891	    "verse": "39",
892	    "ambiguous_marker": false,
893	    "sanskrit_iast": "praviṣṭo nagarīṃ laṅkāṃ laṅghayitvā mahodadhim । kṛtvā mūrdhni padanyāsaṃ rāvaṇasya durātmanaḥ ॥39॥",
894	    "leonov_ru": "Проник я в город Ланку, переправившись через великий океан, Поставив стопу на голову злобного духом Раваны.",
895	    "commentary": {
896	      "bhusana": "कृत्वा मूर्ध्नि पदन्यासं रावणस्य दुरात्मनः ।\n\nत्वां द्रष्टुमुपयातो ऽहं समाश्रित्य पराक्रमम्",
897	      "siromani": "कृत्वेति । अहं रावणस्य मूर्ध्नि पदन्यासं कृत्वा अनादृत्येत्यर्थः, त्वां द्रष्टुमुपयातः"
898	    },
899	    "pratika_check": {
900	      "bhusana": {
901	        "pratika_iast": "krtva nurdhni padanyasan ravanasya",
902	        "matches_verse": true
903	      },
904	      "siromani": {
905	        "pratika_iast": "krtveti",
906	        "matches_verse": true
907	      }
908	    }
