911	    "verse_id": "5.34.40",
912	    "sarga": 34,
913	    "verse": "40",
914	    "ambiguous_marker": false,
915	    "sanskrit_iast": "tvāṃ draṣṭum upayāto 'haṃ samāśritya parākramam । nāham asmi tathā devi yathā mām avagacchasi । viśaṅkā tyajyatām eṣā śraddhatsva vadato mama ॥40॥",
916	    "leonov_ru": "Пришел я, опираясь на [собственную] отвагу, чтобы увидеть тебя. Не тот я, царевна, за кого ты меня принимаешь. Отбрось свои сомнения, поверь моим словам».",
917	    "commentary": {
918	      "tilaka": "यथा मामवगच्छसि मायावी रावण इति, न तथा ऽहमस्मि"
919	    },
920	    "pratika_check": {
921	      "tilaka": {
922	        "pratika_iast": "yatha nanavagacchasi nayavi ravana",
923	        "matches_verse": true
