928	    "verse_id": "5.34.41",
929	    "sarga": 34,
930	    "verse": "41",
931	    "ambiguous_marker": false,
932	    "sanskrit_iast": "",
933	    "leonov_ru": "",
934	    "commentary": {
935	      "bhusana": "नाहमस्मि तथा देवि यथा मामवगच्छसि ।\n\nविशङ्का त्यज्यतामेषा श्रद्धत्स्व वदतो मम\nइत्यार्षे श्रीरामायणे वाल्मीकीये आदिकाव्ये श्रीमत्सुन्दरकाण्डे चतुस्त्रिंशः सर्गः ।। 5.34।।\n\nनाहमिति । वञ्चनार्थं परिगृहीतवेष इति मां यथा ऽवगच्छिसि तथा नास्मीत्यर्थः"
936	    }
