950	    "verse_id": "5.34.1416",
951	    "sarga": 34,
952	    "verse": "1416",
953	    "ambiguous_marker": true,
954	    "sanskrit_iast": "",
955	    "leonov_ru": "",
956	    "commentary": {
957	      "bhusana": "मायावीस्वत एव मायावान् । \"अस्मायामेधास्रजो विनिः\" इति विनिप्रत्ययः । इदानीं मायां प्रविष्टः आश्रितः । स्वयं रावणस्सन् मम सन्तापसुत्पादयसीति यदि उत्पादयसीति  यत् तत्सन्तापोत्पादनं ते न शोभनम् ।। तवाप्यभीष्टविरहसन्तापो भविष्यतीत्यर्थः"
958	    }
959	  },
960	  {
961	    "verse_id": "5.34.1719",
962	    "sarga": 34,
963	    "verse": "1719",
964	    "ambiguous_marker": true,
965	    "sanskrit_iast": "",
966	    "leonov_ru": "",
967	    "commentary": {
968	      "bhusana": "हनुमन्तं रावणमाशङ्क्य तज्जनितमनःप्रसादमालोच्य तां शङ्कां निराचष्टे अथवेति । मया यत् परिशङ्कितम् एतन्नैवं हि नैवमेव । कुत इत्यत आह मनस इति"
969	    }
970	  },
971	  {
972	    "verse_id": "5.34.2122",
973	    "sarga": 34,
974	    "verse": "2122",
975	    "ambiguous_marker": true,
976	    "sanskrit_iast": "",
977	    "leonov_ru": "",
978	    "commentary": {
979	      "bhusana": "स्वप्ने ऽपीति । स्वप्ने ऽपि यद्यहं वीरम् । राक्षसीमध्यवासकृतं दुःखं स्वप्नदृष्टो ऽपि निवर्तयितुं क्षम इति वीर्यातिशयोक्तिः । राघवं सहलक्ष्मणम् । विश्लेषदशायामुभयोर्दर्शनात् स्वप्नदर्शने ऽप्युभयोर्दर्शनं भवेति । यद्वा तदानीमुभयोर्विश्लेषात्तौ किं परस्परं संयुक्तौ न वेति शङ्कते । पश्येयं नावसीदेयम् एवमुभयोस्स्वप्ने दर्शनेपि महत् दुःखं निवर्तेत, कथंजिद् जीवितं धारयेयम् । स्वप्नोपि मम मत्सरी । मद्दशां विज्ञाय राम इव स्वप्नोपि मयि मात्सर्यं करोति"
980	    }
981	  },
982	  {
983	    "verse_id": "5.34.2526",
984	    "sarga": 34,
985	    "verse": "2526",
986	    "ambiguous_marker": true,
987	    "sanskrit_iast": "",
988	    "leonov_ru": "",
989	    "commentary": {
990	      "bhusana": "इत्येवमिति । बलाबलं मोहत्वादीनामबलत्वं रावणत्वस्य बलवत्त्वं च"
991	    }
992	  },
993	  {
994	    "verse_id": "5.34.2829",
995	    "sarga": 34,
996	    "verse": "2829",
997	    "ambiguous_marker": true,
998	    "sanskrit_iast": "",
999	    "leonov_ru": "",
1000	    "commentary": {
1001	      "bhusana": "आदित्य इत्यादि । राजेति कुबेरस्य सर्वलोकराजत्वमुक्तम् \"राजाधिराजाय प्रसह्यसाहिने नमो वयं वैश्रवणाय कुर्महे\" इति । सत्यमधुरावाक्त्वं बृहस्पतेर्वाचस्पतित्वादेव । रूपवान् सौन्दर्यवान् । सुभगः रमणीयः । श्रीमान् कान्तिमान्"
1002	    }
1003	  },
1004	  {
1005	    "verse_id": "5.34.3139",
1006	    "sarga": 34,
1007	    "verse": "3139",
1008	    "ambiguous_marker": true,
1009	    "sanskrit_iast": "",
1010	    "leonov_ru": "",
1011	    "commentary": {
1012	      "tilaka": "तं राघवमाश्रमादपकृष्य शून्य आश्रमे येनापनीता तस्य रक्षसस्तत्फलं त्वदपहारपापफलं तेनानुभूयमानं द्रक्ष्यसि । तदेवाह अचिरादिति । \"नचिरात्\" इति पाठान्तरम् । यो वधिष्यति तेनेत्यर्थः"
1013	    }
1014	  },
1015	  {
1016	    "verse_id": "5.34.3140",
1017	    "sarga": 34,
1018	    "verse": "3140",
1019	    "ambiguous_marker": true,
1020	    "sanskrit_iast": "",
1021	    "leonov_ru": "",
1022	    "commentary": {
1023	      "bhusana": "बहुच्छायामित्यादि । लोकः महात्मनो यस्य बाहुच्छायाम् अवष्टव्यः आश्रितः । तं मृगरूपेण प्रशस्तमृगेण हेतुना आश्रमपदादपकृष्य शून्ये येनापनीतासि तस्य रावणस्य यत्फलं मरणरूपं तत् द्रक्ष्यसीति योजना । यद्वा बाहुच्छायामवष्टब्धो यस्य लोको महात्मनः असावादित्य इव तेजस्वीत्येवं योजना"
1024	    }
1025	  }
1026	]
